self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE_NAME).then(async (cache) => {
      // Per-entry rather than cache.addAll(): addAll is atomic, so one 404 threw
      // the whole precache away and left nothing but a console warning — the app
      // looked installed while being unusable offline. Failures are now reported
      // and skipped, and everything that did fetch is kept.
      const results = await Promise.allSettled(PRECACHE.map(url => cache.add(url)));
      const failed = results
        .map((r, i) => (r.status === 'rejected' ? PRECACHE[i] : null))
        .filter(Boolean);
      if (failed.length) {
        console.warn('[SW] precache skipped ' + failed.length + '/' + PRECACHE.length + ':', failed);
      }
    })
  );
  self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then((cacheNames) => {
      return Promise.all(
        cacheNames.map((cacheName) => {
          if (cacheName !== CACHE_NAME) {
            return caches.delete(cacheName);
          }
        })
      );
    })
  );
  self.clients.claim();
});

// Network-first strategy for dynamic tool loading, fallback to cache
self.addEventListener('fetch', (event) => {
  if (event.request.method !== 'GET') return;
  if (!event.request.url.startsWith('http')) return;

  const url = new URL(event.request.url);
  // Only cache standard HTTP/HTTPS requests
  const isHttp = url.protocol === 'http:' || url.protocol === 'https:';
  // Skip caching local Node bridge API endpoints. /status and /update/* must
  // always hit the network: the update flow polls them to detect the bridge
  // restarting with a new version, and a cached copy would report stale data.
  const isApi = url.pathname === '/detect-project' ||
                url.pathname === '/postgres' ||
                url.pathname === '/m2ee' ||
                url.pathname === '/logs' ||
                url.pathname === '/status' ||
                url.pathname === '/mock-config' ||
                // The mock responder is a live endpoint whose whole point is
                // varying its answer (delay, Chaos Monkey 500s). Caching it
                // would fill the cache with dead responses.
                url.pathname === '/mock' ||
                url.pathname.startsWith('/mock/') ||
                url.pathname === '/project-insights' ||
                url.pathname === '/prometheus' ||
                url.pathname.startsWith('/otel/') ||
                url.pathname.startsWith('/update/') ||
                // Perf Lab polls /perf/stats once a second for the whole run —
                // caching those would fill the cache with hundreds of dead
                // snapshots and could replay a stale one after a network blip.
                url.pathname.startsWith('/perf/') ||
                url.pathname.startsWith('/api/');

  if (!isHttp || isApi) return;

  event.respondWith(
    fetch(event.request)
      .then((response) => {
        if (response && response.status === 200 && (response.type === 'basic' || response.type === 'cors')) {
          const clone = response.clone();
          caches.open(CACHE_NAME).then((cache) => {
            cache.put(event.request, clone).catch(err => {
              console.warn('SW cache put error:', err);
            });
          });
        }
        return response;
      })
      .catch(async () => {
        const cachedResponse = await caches.match(event.request);
        if (cachedResponse) {
          return cachedResponse;
        }
        // Offline navigation fallback: this is a single-page app, so every route
        // resolves to the same shell. Without it, opening the app offline on a
        // URL that missed the cache returned a bare text/plain 404 instead of
        // the app — which reads as "the toolkit is broken", not "you are offline".
        if (event.request.mode === 'navigate') {
          const shell = await caches.match('/index.html');
          if (shell) return shell;
        }
        // If not in cache and network failed, return standard 404 Response instead of undefined
        return new Response('Resource offline or unavailable', {
          status: 404,
          statusText: 'Not Found',
          headers: { 'Content-Type': 'text/plain' }
        });
      })
  );
});
